update public.learning_paths
set
  title = 'Health Economics',
  goal = 'Health Economics',
  summary = 'This course provides an advanced economic analysis of health systems, covering fundamental topics such as the demand for health, healthcare supply, insurance markets, and cost-effectiveness. Students will explore healthcare financing, international comparisons, and value-based care through the lens of public health equity. The curriculum emphasizes practical applications, including budget impact analysis, prevention effectiveness, causal policy evaluation, and global financing strategies, culminating in an applied economic decision memo.',
  data = $heconjson${"slug": "health-economics", "title": "Health Economics", "description": "This course provides an advanced economic analysis of health systems, covering fundamental topics such as the demand for health, healthcare supply, insurance markets, and cost-effectiveness. Students will explore healthcare financing, international comparisons, and value-based care through the lens of public health equity. The curriculum emphasizes practical applications, including budget impact analysis, prevention effectiveness, causal policy evaluation, and global financing strategies, culminating in an applied economic decision memo.", "topics": [{"id": "371f663c-b82b-4c5f-b2c4-eb30ff70c046", "type": "topic", "title": "Economic Thinking for Public Health: Scarcity, Tradeoffs, Incentives, and Equity", "description": "Introduce economics as a practical language for public health choices under limited resources.", "children": [{"id": "08ed7f47-ffaa-4e6a-98de-ac2fffa9cd75", "type": "subtopic", "title": "Scarcity and opportunity cost", "description": "Students learn why public health decisions require choosing among valuable alternatives.", "children": [{"id": "7451f959-e080-4360-a9b4-52667d07d772", "type": "concept", "title": "Limited budgets, workforce, and time"}, {"id": "28035826-8e87-4817-a31c-860797b9816e", "type": "concept", "title": "Opportunity cost in prevention and treatment"}, {"id": "69ba32df-4c2d-42d9-b546-8ad072768615", "type": "concept", "title": "Marginal thinking and tradeoffs"}]}, {"id": "f33b9d6a-b752-4f58-bfd1-dd5eede599ec", "type": "subtopic", "title": "Incentives and behavior", "description": "The point is to see how prices, rules, and institutions shape choices.", "children": [{"id": "8227e39a-70b6-494e-894c-cc16a0b8c1ac", "type": "concept", "title": "Patients, providers, insurers, and governments"}, {"id": "d015a99e-8082-4a1c-925b-3767b6c0e9b1", "type": "concept", "title": "Financial and nonfinancial incentives"}, {"id": "f1d9a25c-cc4f-466b-a0ea-a99760e47f6b", "type": "concept", "title": "Unintended consequences"}]}, {"id": "b09f28bd-ce05-431d-a3dc-eb9312918350", "type": "subtopic", "title": "Efficiency and equity", "description": "Learners distinguish producing more health from distributing health fairly.", "children": [{"id": "3f53004d-28b3-413b-aa34-90ce1bda203b", "type": "concept", "title": "Allocative and technical efficiency"}, {"id": "1b34db08-2f35-4ccd-9005-257fc0e3caaa", "type": "concept", "title": "Horizontal and vertical equity"}, {"id": "52a2c6e2-fa61-4817-914e-ab44caefd5dc", "type": "concept", "title": "Equity-efficiency tradeoffs"}]}]}, {"id": "17b01fb2-e157-408e-9ca7-ea0ea21c42ef", "type": "topic", "title": "Demand for Health, Demand for Healthcare, and Health Behavior", "description": "Explain why people value health, seek care, respond to prices, and make constrained choices.", "children": [{"id": "4c979b66-d9c8-4c1e-9f44-6b9b7db5e600", "type": "subtopic", "title": "Health as a good", "description": "Students examine why health is valued both directly and as a foundation for life opportunities.", "children": [{"id": "9adc41f2-da1d-4bf4-9d98-667048bcce86", "type": "concept", "title": "Health capital and productivity"}, {"id": "f42c2d92-372e-4045-ab5f-e799174bfd4c", "type": "concept", "title": "Prevention versus treatment choices"}, {"id": "9f82bf41-307b-4780-ac98-1dcba69dfbe8", "type": "concept", "title": "Quality of life and wellbeing"}]}, {"id": "6c4dcda4-8823-4902-a2a9-3219c6eaf1ff", "type": "subtopic", "title": "Healthcare demand", "description": "The gist is to understand how need, price, insurance, and information affect care-seeking.", "children": [{"id": "ee471e4f-8264-47b4-bc46-0fe42db39dcd", "type": "concept", "title": "Price elasticity"}, {"id": "8aaf9a96-373f-4fc9-ada0-8bc9dd9ffbd6", "type": "concept", "title": "Supplier-induced demand"}, {"id": "23af2376-5711-4400-af4c-2e8e35750405", "type": "concept", "title": "Information asymmetry"}]}, {"id": "d5dbfedc-78fe-4740-bf07-b96e82199fb9", "type": "subtopic", "title": "Behavior and constraints", "description": "Learners connect economics with social and behavioral determinants.", "children": [{"id": "397ab351-444d-444c-a279-8a3c935e4f33", "type": "concept", "title": "Time, transportation, and affordability"}, {"id": "9ac921a7-5586-4ac4-a41b-2ca2455cabb4", "type": "concept", "title": "Health literacy and trust"}, {"id": "4ea5d6b9-d9f0-4cb6-aef6-92c32f132ac3", "type": "concept", "title": "Behavioral economics and nudges"}]}]}, {"id": "4322e25d-f709-486e-9d31-35b108c11433", "type": "topic", "title": "Supply of Healthcare: Providers, Hospitals, Workforce, Pharmaceuticals, and Technology", "description": "Analyze how healthcare production, labor, organizations, and innovation shape cost, access, and quality.", "children": [{"id": "bbe4dc65-c690-4f81-b1da-c181dc82c231", "type": "subtopic", "title": "Provider and hospital behavior", "description": "Students learn how organizations produce care and respond to payment rules.", "children": [{"id": "8b19cfb4-ddb7-48ea-a3c2-64ffa249b137", "type": "concept", "title": "Fixed and variable costs"}, {"id": "a089174f-ad98-47e3-ae37-7368e0547aee", "type": "concept", "title": "Capacity and staffing"}, {"id": "b1a3e576-196d-4e61-b1d1-63e7110f91b8", "type": "concept", "title": "Service lines and specialization"}]}, {"id": "54b4cd76-61d5-463c-b58f-9447507f18a3", "type": "subtopic", "title": "Workforce economics", "description": "The point is to connect labor supply to access, quality, and cost.", "children": [{"id": "1a14c13f-62f1-47af-b6c7-fb1ee6ba7e3c", "type": "concept", "title": "Training pipelines"}, {"id": "737d4dd7-a3c3-4303-b820-2215bc1c8fb4", "type": "concept", "title": "Scope of practice"}, {"id": "2bd3e4a7-c6c0-427c-ba37-a581a645c441", "type": "concept", "title": "Geographic maldistribution"}]}, {"id": "82f14493-33dd-43dd-9506-d8cda720df8d", "type": "subtopic", "title": "Pharmaceuticals and technology", "description": "Learners analyze innovation, pricing, and adoption.", "children": [{"id": "0b5b4562-e5f0-4609-8c06-c54cff6145dd", "type": "concept", "title": "Research and development incentives"}, {"id": "7afd53c5-f379-4f58-9286-7f990c7c27a8", "type": "concept", "title": "Patents and market exclusivity"}, {"id": "57ab9606-6b91-42c9-a3f1-b238bb05a581", "type": "concept", "title": "Technology diffusion and overuse"}]}]}, {"id": "065d1e12-9ec1-4e53-8847-465a1538b7fe", "type": "topic", "title": "Health Insurance, Risk Pooling, Adverse Selection, Moral Hazard, and Managed Care", "description": "Understand how insurance spreads risk while creating incentive and affordability challenges.", "children": [{"id": "64d6cee2-bb0d-427b-91b4-39888ba34bf4", "type": "subtopic", "title": "Risk pooling", "description": "Students learn how insurance protects people from financial uncertainty.", "children": [{"id": "3d1819be-b02b-4548-957a-b5f089eec287", "type": "concept", "title": "Premiums and expected costs"}, {"id": "9c07febc-9e4a-4168-b5d7-2e78919ad818", "type": "concept", "title": "Risk adjustment"}, {"id": "08f2e9af-3e5a-4be4-8f6f-61f6360c15d4", "type": "concept", "title": "Community rating and experience rating"}]}, {"id": "8dd811b9-0585-49cc-a294-23cbfed01589", "type": "subtopic", "title": "Selection and moral hazard", "description": "The gist is to understand classic insurance market problems.", "children": [{"id": "468671b4-c770-47f0-9228-8b49dac13383", "type": "concept", "title": "Adverse selection"}, {"id": "e46b05dd-06a5-4f7a-99af-77b981526230", "type": "concept", "title": "Ex ante and ex post moral hazard"}, {"id": "fb732155-33a0-4f1e-832f-f695c2a01eb4", "type": "concept", "title": "Cost sharing and utilization management"}]}, {"id": "b71593d8-634f-4553-9d7d-e0230a5bf935", "type": "subtopic", "title": "Managed care and plan design", "description": "Learners evaluate how insurers shape care access and cost.", "children": [{"id": "9e8f31cf-cede-4c75-ba8b-54a1cf416bf6", "type": "concept", "title": "Networks and prior authorization"}, {"id": "fb6babd1-3674-46c6-a63a-e5fb460fd944", "type": "concept", "title": "Deductibles, copays, and coinsurance"}, {"id": "3b2d765b-bfab-483c-9554-44d53feb5a58", "type": "concept", "title": "Benefit design and formularies"}]}]}, {"id": "1c7741da-1ef5-4076-897b-d5efbe8bce2c", "type": "topic", "title": "Health Markets, Market Failure, Externalities, Public Goods, and Government Intervention", "description": "Use economic theory to explain why healthcare markets often require regulation, subsidy, or public provision.", "children": [{"id": "86fad638-f12f-459e-a58d-097bf778b1ea", "type": "subtopic", "title": "Market failure in health", "description": "Students learn why healthcare often differs from textbook competitive markets.", "children": [{"id": "2f307dfa-d40d-4d1d-85d0-a2a39953c30f", "type": "concept", "title": "Information asymmetry"}, {"id": "43a6e1df-dc3d-4d55-b32a-9040cd166ad7", "type": "concept", "title": "Market power"}, {"id": "19b553fe-ac05-47d8-a3e2-6db7247df710", "type": "concept", "title": "Uncertainty and urgency"}]}, {"id": "2a7a054b-6300-4110-a71f-305cbe3c4e18", "type": "subtopic", "title": "Public health externalities", "description": "The point is to value effects that spill beyond the individual patient.", "children": [{"id": "c0a13720-bcb6-4b1d-8a6e-1bb5c38737e9", "type": "concept", "title": "Vaccination and herd protection"}, {"id": "d621187f-c6cf-45b8-8e2c-4bbd8894d421", "type": "concept", "title": "Communicable disease control"}, {"id": "0e1a6c25-a2ee-4634-8798-f033e0741815", "type": "concept", "title": "Pollution and injury prevention"}]}, {"id": "4b4853d3-3e01-41df-868b-6990fe711dca", "type": "subtopic", "title": "Policy tools", "description": "Learners compare intervention options.", "children": [{"id": "9f373568-edfa-4f7a-aaaf-4d236b1f686b", "type": "concept", "title": "Regulation and mandates"}, {"id": "c7395556-b1eb-4ae9-baca-62952b04a62c", "type": "concept", "title": "Taxes, subsidies, and vouchers"}, {"id": "1b2817ce-620e-4a98-980e-9fa9a7976527", "type": "concept", "title": "Public provision and social insurance"}]}]}, {"id": "9c08ee84-4160-4eb5-b690-5f2a0507a8b9", "type": "topic", "title": "Healthcare Financing: Medicare, Medicaid, Employer Coverage, ACA, Taxes, and Out-of-Pocket Costs", "description": "Compare major financing systems and how they affect access, spending, and equity.", "children": [{"id": "49c51f3a-84a6-4726-b429-ce822d8dae83", "type": "subtopic", "title": "U.S. financing mix", "description": "Students map the major public and private payers.", "children": [{"id": "562aaf7a-1bf1-4425-8179-fee5f92793c9", "type": "concept", "title": "Medicare"}, {"id": "ae4fd398-efdb-4595-9594-813048e25980", "type": "concept", "title": "Medicaid and CHIP"}, {"id": "ec4e92b3-e57a-4c33-9a5b-a01fdaffa68d", "type": "concept", "title": "Employer-sponsored and individual market coverage"}]}, {"id": "bab79841-5a43-48cb-bcff-3595000d02f0", "type": "subtopic", "title": "Coverage policy", "description": "The gist is to see how eligibility and benefits affect access.", "children": [{"id": "bd044e69-ceed-4757-974f-bebcbc711d80", "type": "concept", "title": "ACA marketplaces and subsidies"}, {"id": "4e228324-d418-4185-8aaf-121c64d3e989", "type": "concept", "title": "Medicaid expansion"}, {"id": "f57a3a1e-8c5f-49aa-bec7-566d91c9d1b9", "type": "concept", "title": "Underinsurance and churn"}]}, {"id": "f43cfa5e-2080-45e6-bef1-e649a1dcd4df", "type": "subtopic", "title": "Household financial burden", "description": "Learners assess affordability from the patient perspective.", "children": [{"id": "445886f7-dc63-41c4-a646-50f3fc75b94a", "type": "concept", "title": "Premiums and cost sharing"}, {"id": "fad2d4aa-1016-4799-9968-4eb9fd53cdf9", "type": "concept", "title": "Medical debt"}, {"id": "08098c7c-d3b2-4d0f-a9ba-7bce8ed0e4be", "type": "concept", "title": "Out-of-pocket maximums and surprise bills"}]}]}, {"id": "ac0ad339-42d4-4292-be25-0be9d80a3696", "type": "topic", "title": "Health Spending, Prices, Utilization, Affordability, and Cost Drivers", "description": "Interpret spending trends and distinguish price, quantity, intensity, and administrative drivers.", "children": [{"id": "97a53e31-7580-44c1-972f-572d0f9a4b2b", "type": "subtopic", "title": "Spending decomposition", "description": "Students learn to distinguish why spending rises.", "children": [{"id": "fcbacf08-f289-47cc-9380-b60752dcef8c", "type": "concept", "title": "Prices versus quantities"}, {"id": "76d26ff6-122a-4855-87cc-4ceddc2cf3bf", "type": "concept", "title": "Population aging and disease burden"}, {"id": "9e3efe67-8222-4272-ba22-366ca5063017", "type": "concept", "title": "Technology, intensity, and administrative costs"}]}, {"id": "4111eb47-6906-4680-98d5-cf34efd53ece", "type": "subtopic", "title": "Price and payment variation", "description": "The point is to understand why the same service can cost different amounts.", "children": [{"id": "2010ce98-440f-4f40-9a1b-916cb262418e", "type": "concept", "title": "Negotiated prices"}, {"id": "61acbf37-e0bd-499f-a5a0-06996ac2045d", "type": "concept", "title": "Facility fees and site of care"}, {"id": "d011c4d3-093a-4e4e-ab87-c6cb1301d554", "type": "concept", "title": "Public versus private payment rates"}]}, {"id": "6c8434b5-1928-4c77-8de2-270a0d943ea7", "type": "subtopic", "title": "Affordability and value", "description": "Learners interpret cost burden alongside health outcomes.", "children": [{"id": "8f096b92-be65-474c-a7be-d45086a58771", "type": "concept", "title": "Premium affordability"}, {"id": "3155825d-eef5-4d24-a9da-091b8247f22c", "type": "concept", "title": "High-cost drugs and services"}, {"id": "59e54597-7ae1-4c91-84e1-ccaca7c5e4a6", "type": "concept", "title": "Waste, low-value care, and value measurement"}]}]}, {"id": "79835b43-003f-4500-9680-5fe47cfaacb4", "type": "topic", "title": "Economic Evaluation Foundations: Perspective, Costs, Outcomes, Discounting, and Decision Models", "description": "Build the methodological base for comparing public health and healthcare interventions.", "children": [{"id": "0b2c44f2-bbc2-41c7-b491-52a76eff06bf", "type": "subtopic", "title": "Evaluation perspective", "description": "Students learn that results depend on whose costs and benefits count.", "children": [{"id": "924e1854-620a-4339-ad0d-dea77b9c0776", "type": "concept", "title": "Societal, payer, patient, and healthcare-sector perspectives"}, {"id": "a2956b59-842e-435c-9e88-e8d75a74b09b", "type": "concept", "title": "Direct, indirect, and intangible costs"}, {"id": "7e1e80b5-9a05-48db-b1d8-28749dd1bbd4", "type": "concept", "title": "Equity and stakeholder perspectives"}]}, {"id": "f496dceb-b4d1-4d3e-882e-bcb82207e859", "type": "subtopic", "title": "Costs and outcomes", "description": "The gist is to measure inputs and effects consistently.", "children": [{"id": "ae017156-718e-4772-8c4b-e8bef4972219", "type": "concept", "title": "Program, medical, and productivity costs"}, {"id": "95cc4312-4437-42eb-b137-ba0cec018ad6", "type": "concept", "title": "Natural units and health outcomes"}, {"id": "f4399897-5ed4-4958-8d9c-cafe192b83ed", "type": "concept", "title": "Time horizon and discounting"}]}, {"id": "3ab04ee9-4f50-47b8-aaf8-781656fa23ec", "type": "subtopic", "title": "Decision models", "description": "Learners represent choices under uncertainty.", "children": [{"id": "5cf3102d-6daf-47aa-9690-5fa11e6f626d", "type": "concept", "title": "Decision trees"}, {"id": "fb0da339-8ac7-4a05-80ad-0bbc0eada8b1", "type": "concept", "title": "Markov models"}, {"id": "7a84ed98-2c1b-4e42-8c23-6b0092532aa5", "type": "concept", "title": "Model assumptions and transparency"}]}]}, {"id": "c658e45a-12f6-45c7-a53f-3a95fa907b9f", "type": "topic", "title": "Cost-Effectiveness and Cost-Utility Analysis: ICERs, QALYs, DALYs, and Uncertainty", "description": "Apply standard health economic evaluation tools to prevention, treatment, and policy choices.", "children": [{"id": "d1a32f27-0082-4a9e-94e7-bab1bb305e8e", "type": "subtopic", "title": "Cost-effectiveness analysis", "description": "Students compare interventions using incremental costs and outcomes.", "children": [{"id": "3be7570d-20ff-4eab-a997-93feb0d3b9b2", "type": "concept", "title": "Incremental cost-effectiveness ratios"}, {"id": "3fa6d6f3-77aa-4960-86e1-dadf3fa7bfcc", "type": "concept", "title": "Dominance and extended dominance"}, {"id": "d80ed78f-3fa2-4f3f-9638-4b45ff8008b4", "type": "concept", "title": "Efficiency frontiers"}]}, {"id": "3d209d87-ee1f-44c2-a7d6-e4395d2881bd", "type": "subtopic", "title": "Utility and burden measures", "description": "The point is to use common outcome units for comparison.", "children": [{"id": "3d8953c6-5853-4a59-b349-cfa5ca5e4863", "type": "concept", "title": "QALYs"}, {"id": "09bd143e-d15a-4d97-bd96-2ac689e24b99", "type": "concept", "title": "DALYs"}, {"id": "18d7ba96-d9b4-4dae-889e-7dbf89061744", "type": "concept", "title": "Health-related quality of life weights"}]}, {"id": "288afcde-5826-4a08-91a2-9b54425c6854", "type": "subtopic", "title": "Uncertainty and sensitivity", "description": "Learners test whether conclusions are robust.", "children": [{"id": "7dbd579a-1b6c-4a1e-8b08-263f949d697b", "type": "concept", "title": "One-way and probabilistic sensitivity analysis"}, {"id": "07c823eb-15dd-4d86-8e76-3875cc601c5e", "type": "concept", "title": "Scenario analysis"}, {"id": "ec93efd5-0a4c-4039-8491-e2799a93428f", "type": "concept", "title": "Cost-effectiveness acceptability curves"}]}]}, {"id": "793b25bb-43b9-4e20-9a22-b7f5360057d7", "type": "topic", "title": "Cost-Benefit Analysis, Budget Impact, Return on Investment, and Prevention Effectiveness", "description": "Assess programs using monetary benefits, payer budgets, and public health prevention value.", "children": [{"id": "026cd1ce-1e3d-45a9-95bc-a45aab24c23b", "type": "subtopic", "title": "Cost-benefit analysis", "description": "Students learn when benefits are converted into monetary terms.", "children": [{"id": "a84abfa4-4497-4e9a-ac78-4a83fc9c9cba", "type": "concept", "title": "Willingness to pay"}, {"id": "ed63c72a-b99e-41f1-89fe-1beff75fc68e", "type": "concept", "title": "Net benefits and benefit-cost ratios"}, {"id": "e9c4f0bd-3284-4e13-a79f-905391f3093c", "type": "concept", "title": "Valuing mortality and morbidity reductions"}]}, {"id": "08657799-eae5-4677-8735-7547d9c25504", "type": "subtopic", "title": "Budget impact and ROI", "description": "The gist is to connect economic value to feasible budgets.", "children": [{"id": "2759d6a7-1892-4668-a18d-f08b6b0d4e7f", "type": "concept", "title": "Short-term budget impact"}, {"id": "06332a6b-988b-487f-9230-1f0be3845d2f", "type": "concept", "title": "Return on investment"}, {"id": "783b2cab-c7e0-4326-9886-72828713d8b8", "type": "concept", "title": "Payer versus societal savings"}]}, {"id": "28f66b51-5bf0-4b1e-9fdc-b59415ed063e", "type": "subtopic", "title": "Prevention effectiveness", "description": "Learners evaluate public health interventions beyond clinical care.", "children": [{"id": "4c66e69b-5af7-4957-8500-4de5b3daf753", "type": "concept", "title": "Screening programs"}, {"id": "8c5f9a6a-5c30-4144-95f3-6d73fb01dafe", "type": "concept", "title": "Vaccination and chronic disease prevention"}, {"id": "bc3f7d84-ca5f-4609-a43f-ce4ab58a6c17", "type": "concept", "title": "Community-level interventions"}]}]}, {"id": "9079997c-9cd3-4bd5-91b8-43cf0ae12ebe", "type": "topic", "title": "Equity, Social Determinants, Distributional Analysis, and Health Justice", "description": "Evaluate who benefits, who pays, and how economic analysis can include equity concerns.", "children": [{"id": "29a9a09d-3332-4660-b35c-b7b6706e04f3", "type": "subtopic", "title": "Economic inequality and health", "description": "Students connect income, wealth, and structural conditions to health outcomes.", "children": [{"id": "e8498917-98ce-4f52-9fd4-424eca68db99", "type": "concept", "title": "Social gradient in health"}, {"id": "64dacfbf-62ca-4a68-b88b-4697ebb0b5f3", "type": "concept",